package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.client.Minecraft;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.phys.*;import net.minecraft.world.item.context.BlockPlaceContext;import com.mojang.math.Axis;
@net.minecraftforge.fml.common.Mod.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID,value=net.minecraftforge.api.distmarker.Dist.CLIENT)
public final class Uf01Preview {
 static BlockPos root;static Direction facing;static boolean valid;static net.minecraft.client.multiplayer.ClientLevel level;static long checked;
 @net.minecraftforge.eventbus.api.SubscribeEvent public static void tick(net.minecraftforge.event.TickEvent.ClientTickEvent e){if(e.phase!=net.minecraftforge.event.TickEvent.Phase.END)return;var m=Minecraft.getInstance();if(m.level==null||m.player==null||m.screen!=null){root=null;level=null;return;}InteractionHand hand=m.player.getMainHandItem().getItem()instanceof Uf01Item?InteractionHand.MAIN_HAND:m.player.getOffhandItem().getItem()instanceof Uf01Item?InteractionHand.OFF_HAND:null;if(hand==null||!(m.hitResult instanceof BlockHitResult hit)||hit.getType()!=HitResult.Type.BLOCK){root=null;return;}var c=new BlockPlaceContext(m.player,hand,m.player.getItemInHand(hand),hit);var pos=c.getClickedPos();var f=c.getHorizontalDirection();if(!pos.equals(root)||facing!=f||level!=m.level||m.level.getGameTime()-checked>=5){root=pos.immutable();facing=f;level=m.level;checked=level.getGameTime();valid=Uf01Item.clear(c);}}
 @net.minecraftforge.eventbus.api.SubscribeEvent public static void render(net.minecraftforge.client.event.RenderLevelStageEvent e){if(e.getStage()!=net.minecraftforge.client.event.RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS||root==null||Minecraft.getInstance().level!=level)return;var m=Minecraft.getInstance();var poses=e.getPoseStack();var cam=e.getCamera().getPosition();poses.pushPose();poses.translate(root.getX()+.5-cam.x,root.getY()-cam.y,root.getZ()+.5-cam.z);poses.mulPose(Axis.YP.rotationDegrees(270-facing.toYRot()));float partial=e.getPartialTick();Uf01Model.get().draw(poses,m.renderBuffers().bufferSource(),net.minecraft.client.renderer.LevelRenderer.getLightColor(level,root),net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY,(Math.floorMod(level.getGameTime(),80)+partial)/20d,Math.max(level.getRainLevel(partial),level.getThunderLevel(partial)),true,valid);poses.popPose();}
}
